  "game.gameSavedAllPlayersDesc": { de: "Alle Spieler wurden erfasst — der Turnierverlauf im Klassiker-Datensatz zeigt aber nur die Top 2.", en: "All players were recorded — but the tournament history in the classic dataset only shows the top 2.", fr: "Tous les joueurs ont été enregistrés — mais l'historique du tournoi dans le jeu de données classique n'affiche que le top 2.", pl: "Zarejestrowano wszystkich graczy — ale historia turnieju w klasycznym zestawie danych pokazuje tylko top 2.", nl: "Alle spelers zijn geregistreerd — maar de toernooigeschiedenis in de klassieke dataset toont alleen de top 2.", tr: "Tüm oyuncular kaydedildi — ancak klasik veri kümesindeki turnuva geçmişi yalnızca ilk 2'yi gösterir." },
  "game.tournamentPending": { de: "Turnier wird nachgetragen", en: "Tournament update pending", fr: "Mise à jour du tournoi en attente", pl: "Aktualizacja turnieju w toku", nl: "Toernooi wordt bijgewerkt", tr: "Turnuva güncellemesi bekliyor" },
  "game.tournamentPendingDesc": { de: "Ergebnis konnte gerade nicht in den Turnierbaum übernommen werden — wird automatisch nachgeholt.", en: "Couldn't write the result into the bracket just now — it'll be retried automatically.", fr: "Impossible d'inscrire le résultat dans le tableau pour le moment — nouvelle tentative automatique.", pl: "Nie udało się teraz wpisać wyniku do drabinki — zostanie to powtórzone automatycznie.", nl: "Kon het resultaat nu niet in het schema opslaan — wordt automatisch opnieuw geprobeerd.", tr: "Sonuç şu anda turnuva tablosuna yazılamadı — otomatik olarak tekrar denenecek." },
  "game.savedOfflineTitle": { de: "Offline gespeichert", en: "Saved offline", fr: "Enregistré hors ligne", pl: "Zapisano offline", nl: "Offline opgeslagen", tr: "Çevrimdışı kaydedildi" },
  "game.savedOfflineWithLinkDesc": { de: "Keine Verbindung — Ergebnis und Turnier-Eintrag bleiben auf diesem Gerät und synchronisieren automatisch, sobald wieder Netz da ist.", en: "No connection — the result and bracket entry stay on this device and sync automatically once back online.", fr: "Pas de connexion — le résultat et l'entrée du tournoi restent sur cet appareil et se synchroniseront dès le retour du réseau.", pl: "Brak połączenia — wynik i wpis turniejowy pozostają na tym urządzeniu i zsynchronizują się automatycznie po powrocie sieci.", nl: "Geen verbinding — resultaat en toernooi-invoer blijven op dit apparaat en synchroniseren automatisch zodra er weer netwerk is.", tr: "Bağlantı yok — sonuç ve turnuva kaydı bu cihazda kalır ve bağlantı geri gelince otomatik olarak senkronize edilir." },
  "game.savedOfflineNoLinkDesc": { de: "Keine Verbindung — das Ergebnis bleibt auf diesem Gerät und synchronisiert automatisch, sobald wieder Netz da ist.", en: "No connection — the result stays on this device and syncs automatically once back online.", fr: "Pas de connexion — le résultat reste sur cet appareil et se synchronisera dès le retour du réseau.", pl: "Brak połączenia — wynik pozostaje na tym urządzeniu i zsynchronizuje się automatycznie po powrocie sieci.", nl: "Geen verbinding — het resultaat blijft op dit apparaat en synchroniseert automatisch zodra er weer netwerk is.", tr: "Bağlantı yok — sonuç bu cihazda kalır ve bağlantı geri gelince otomatik olarak senkronize edilir." },
  "game.saveFailedQueuedTitle": { de: "Speichern fehlgeschlagen", en: "Save failed", fr: "Échec de l'enregistrement", pl: "Zapis nie powiódł się", nl: "Opslaan mislukt", tr: "Kaydetme başarısız" },
  "game.saveFailedQueuedDesc": { de: "Das Ergebnis bleibt auf diesem Gerät und wird automatisch erneut versucht — falls das öfter passiert, versuch dich einmal ab- und wieder anzumelden.", en: "The result stays on this device and will retry automatically — if this keeps happening, try signing out and back in.", fr: "Le résultat reste sur cet appareil et sera automatiquement retenté — si cela persiste, essaie de te déconnecter puis reconnecter.", pl: "Wynik pozostaje na tym urządzeniu i spróbuje ponownie automatycznie — jeśli to się powtarza, spróbuj się wylogować i zalogować ponownie.", nl: "Het resultaat blijft op dit apparaat en wordt automatisch opnieuw geprobeerd — als dit blijft gebeuren, probeer uit- en weer in te loggen.", tr: "Sonuç bu cihazda kalır ve otomatik olarak tekrar denenecek — bu tekrar oluyorsa, oturumu kapatıp tekrar açmayı dene." },

