  "camera.modelLoadingCalib": { de: "KI-Modell lädt – suche Kalibrierpunkte …", en: "AI model loading – searching for calibration points …", fr: "Chargement du modèle IA – recherche des points d'étalonnage…", pl: "Ładowanie modelu AI – szukanie punktów kalibracji…", nl: "AI-model laadt – kalibratiepunten zoeken …", tr: "AI modeli yükleniyor – kalibrasyon noktaları aranıyor…" },
  "camera.autoCalibratedReady": { de: "Automatisch kalibriert (KI-Modell) · bereit – wirf deinen ersten Dart. Stimmt die Lage nicht, unten „Kalibrierung neu starten“ tippen.", en: "Auto-calibrated (AI model) · ready – throw your first dart. If the position looks off, tap “Restart calibration” below.", fr: "Étalonné automatiquement (modèle IA) · prêt – lance ta première fléchette. Si la position ne convient pas, touche « Redémarrer l'étalonnage » ci-dessous.", pl: "Skalibrowano automatycznie (model AI) · gotowe – rzuć pierwszą lotkę. Jeśli pozycja się nie zgadza, dotknij poniżej „Zrestartuj kalibrację”.", nl: "Automatisch gekalibreerd (AI-model) · klaar – gooi je eerste dart. Klopt de positie niet, tik dan hieronder op “Kalibratie herstarten”.", tr: "Otomatik kalibre edildi (AI modeli) · hazır – ilk dartını at. Konum doğru değilse aşağıdan “Kalibrasyonu yeniden başlat”a dokunun." },
