  "tournament.matchNotLiveExtern": { de: "Diese Runde wird extern gespielt – kein Live-Spiel über die App.", en: "This round is played outside the app — no live game here.", fr: "Cette manche se joue en dehors de l'application — pas de partie en direct ici.", nl: "Deze ronde wordt buiten de app gespeeld — geen live spel hier.", pl: "Ta runda jest rozgrywana poza aplikacją — bez gry na żywo tutaj.", tr: "Bu tur uygulama dışında oynanıyor — burada canlı oyun yok." },
