  "tournament.emptyMeansBye": { de: "Leer lassen = Freilos (BYE). Ergebnisse dieser Partie werden zurückgesetzt.", en: "Leave empty = bye (BYE). Results of this match will be reset.", fr: "Laisser vide = exempt (BYE). Les résultats de ce match seront réinitialisés.", pl: "Pozostaw puste = wolny los (BYE). Wyniki tego meczu zostaną zresetowane.", nl: "Leeg laten = vrijlot (BYE). Resultaten van deze wedstrijd worden gereset.", tr: "Boş bırak = bay (BYE). Bu maçın sonuçları sıfırlanacak." },
  "tournament.player1ByePlaceholder": { de: "Spieler 1 (leer = BYE)", en: "Player 1 (empty = BYE)", fr: "Joueur 1 (vide = BYE)", pl: "Gracz 1 (puste = BYE)", nl: "Speler 1 (leeg = BYE)", tr: "Oyuncu 1 (boş = BYE)" },
  "tournament.player2ByePlaceholder": { de: "Spieler 2 (leer = BYE)", en: "Player 2 (empty = BYE)", fr: "Joueur 2 (vide = BYE)", pl: "Gracz 2 (puste = BYE)", nl: "Speler 2 (leeg = BYE)", tr: "Oyuncu 2 (boş = BYE)" },
  "tournament.editModeForRound": { de: "Modus für Runde", en: "Mode for round", fr: "Mode pour le tour", pl: "Tryb dla rundy", nl: "Modus voor ronde", tr: "Tur için mod" },
  "tournament.editHeadingSuffix": { de: "bearbeiten", en: "edit", fr: "modifier", pl: "edytuj", nl: "bewerken", tr: "düzenle" },
  "tournament.roundModeScopeNote": { de: "Gilt nur für diese Runde, nicht für den Rest des Turniers — und nur solange noch keine Partie darin entschieden ist.", en: "Applies only to this round, not the rest of the tournament — and only as long as no match in it has been decided yet.", fr: "S'applique uniquement à ce tour, pas au reste du tournoi — et seulement tant qu'aucun match n'y a été décidé.", pl: "Dotyczy tylko tej rundy, nie reszty turnieju — i tylko dopóki żaden mecz w niej nie został rozstrzygnięty.", nl: "Geldt alleen voor deze ronde, niet voor de rest van het toernooi — en alleen zolang er nog geen wedstrijd in is beslist.", tr: "Yalnızca bu tur için geçerlidir, turnuvanın geri kalanı için değil — ve içindeki hiçbir maç henüz sonuçlanmadığı sürece." },
  "tournament.liveTickerHeading": { de: "Live-Ticker · Turnierverlauf", en: "Live ticker · tournament progress", fr: "Fil en direct · progression du tournoi", pl: "Ticker na żywo · przebieg turnieju", nl: "Live-ticker · toernooiverloop", tr: "Canlı akış · turnuva ilerlemesi" },
